import java.time.LocalDate;

public class Main {
    public static void main(String[] args) {
        LocalDate 本喵这张 = LocalDate.of(2026, {m1}, 31);

        System.out.println("这个月有几天：" + 本喵这张.lengthOfMonth());
        System.out.println("拉到 1 号：" + 本喵这张.withDayOfMonth(1));
        System.out.println("往后挪一个月：" + 本喵这张.plusMonths(1));
    }
}
